import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第105章 对不起","description":"","frontmatter":{},"headers":[],"relativePath":"第105章_对不起.md","filePath":"第105章_对不起.md"}'),_={name:"第105章_对不起.md"};function u(r,p,q,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第105章-对不起" tabindex="-1">第105章 对不起 <a class="header-anchor" href="#第105章-对不起" aria-label="Permalink to &quot;第105章 对不起&quot;">​</a></h1><p>第二年开春，我们漏发了一件。</p><p>那件东西很小。</p><p>是一个立牌，一个人物，二十几块。</p><p>那天我发的是十一件，装在一个袋子里。</p><p>那个客人后来发消息说，她只有十件。</p><p>我翻了我当天的记录。</p><p>我记的是十一。</p><p>我数了我贴掉的单号，十一。</p><p>我把那个袋子从她的退回里拿出来，重新点。</p><p>十件。</p><p>少了一件。</p><p>我在我们那个仓库里找了一个半小时。</p><p>我把那一层所有的袋子拆开。</p><p>我把每一个袋子里的东西倒在地上，一件一件数，数完装回去。</p><p>我们那间屋子那天下午像被偷过。</p><p>我没找到。</p><p>我给她发了一句。</p><p>我说，我这里少一件，我赔。</p><p>她隔了两分钟。</p><p>她说，多少钱。</p><p>我说，二十四。</p><p>她说，你查过进货单了吗。</p><p>我说，查了。</p><p>她说，进货单上是多少。</p><p>我说，十一。</p><p>她说，你确定你发的时候是十一。</p><p>我说，我数了两遍。</p><p>她说，你数了两遍你还是少一件。</p><p>我说，对。</p><p>她说，那你查一下那个客人是不是那天到了以后拆的时候掉了。</p><p>我说，人家说没掉。</p><p>她说，那查快递。</p><p>我说，快递说他们不拆包。</p><p>她说，那你查是不是我这边装的时候就少。</p><p>我说，你装的时候我这边没在。</p><p>她说，对，我们这边有两个人装。</p><p>她说，我今天回去问。</p><p>那天晚上她回了。</p><p>她说，我们这边那天少放了一件。</p><p>她说，那个立牌那天早上断货，我先给另一单挪走了，我忘了改你那边的数。</p><p>她说，不是你的问题。</p><p>我说，那就是了。</p><p>她说，对不起。</p><p>我看到那三个字，坐在那里很久。</p><p>我那天下午在找那一件东西的时候，我心里其实很清楚。</p><p>我找的不是那一件立牌。</p><p>我在证明一件事：我这边的十一是对的。</p><p>我这几年在她面前所有力气，都花在这种小事的对错上。</p><p>她一句&quot;对不起&quot;，把我这一整个下午全部没收了。</p><p>因为她说的是她错了。</p><p>她说她错了，我就只能回一句&quot;不是你的问题&quot;。</p><p>而&quot;不是你的问题&quot;这一句，我这一辈子讲得太熟了。</p><p>我打的是：不是你的问题。</p><p>打完我看那六个字。</p><p>我把它删了。</p><p>我重新打。</p><p>我打的是：我今天下午把所有袋子都拆了。</p><p>她隔了一会儿。</p><p>她说，我知道，你今天一直没回我。</p><p>我说，我不是在告诉你我多累。</p><p>她说，我知道你不是。</p><p>她说，你讲这句是你今天不想讲&quot;不是你的问题&quot;。</p><p>我说，对。</p><p>她说，那你说什么。</p><p>我说，我说这件二十四，我出十二，你出十二。</p><p>她隔了很久。</p><p>她说，你说什么？</p><p>我说，你那边挪走了一件，我这边少了一件没查出来。</p><p>我说，一人一半。</p><p>她说，我这边有记录，是我的责任。</p><p>我说，你那边有记录，我这边的记录是我自己写的，我的记录不干净。</p><p>她说，你今天怎么这么烦。</p><p>我说，我今天要定这个。</p><p>她说，不用定。</p><p>我说，要定。</p><p>她说，闻迟，你要是定这个，我今天晚上就要开始想这件事。</p><p>我说，你想什么。</p><p>她说，我想你为什么要平分。</p><p>她说，你要是为了公平，你今天不用把那个立牌赔给客人。</p><p>她说，你下午三点就可以告诉我，你说&quot;我这里十一件没错，是她那边少放&quot;。</p><p>她说，你没有。</p><p>她说，你找了一个半小时。</p><p>她说，你找一个半小时你才来找我。</p><p>她说，你今天这个平分，是你给自己找的一个台阶。</p><p>我说，你讲话太难听。</p><p>她说，我知道。</p><p>她说，我今天不想好听。</p><p>她说，我今天要是跟你讲一句&quot;你真好，我们一人一半&quot;，那我们这一单明天就不是生意了。</p><p>她说，你今天这个&quot;一人一半&quot;，你要的不是钱。</p><p>她说，你要的是以后你不用查快递。</p><p>她说，你要的是以后出了错，我们两个都错。</p><p>她说，你这个人你在替我们两个想一个谁都不用道歉的做法。</p><p>我说，那你不同意。</p><p>她说，我同意。</p><p>我说，你为什么不同意。</p><p>她说，我同意这一人一半。</p><p>她说，我不同意的是你以为我看不出来。</p><p>她说，我告诉你我看出来了，你今天就会难受。</p><p>她说，我如果不看，我们明天还能对账。</p><p>我说，你今天讲了，明天我们还对。</p><p>她说，不一定。</p><p>她说，我今天讲了这一句，我明天就要开始注意你什么时候在替我想。</p><p>她说，我一注意，我就开始挑。</p><p>她说，我一开始挑，我们两个就不是同事了。</p><p>她说，我不想当我们两个是同事。</p><p>她说，可是我这一辈子只有当我们是同事的时候我才不慌。</p><p>我说，那你今天就慌了。</p><p>她没回。</p><p>那天晚上十二点二十，她发了一句。</p><p>她说，二十四块我转给你。</p><p>我说，你说了一人一半。</p><p>她说，我改主意了。</p><p>她说，我今天晚上不想跟你一人一半。</p><p>我说，为什么。</p><p>她说，因为今晚这一半是你替我想的，我不要别人替我想的一半。</p><p>她说，我自己全出。</p><p>她说，你别讲，你讲了我也不改。</p><p>我说，那你把十二收着。</p><p>她说，你先把这个记到本上。</p><p>我说，我记。</p><p>她说，你写&quot;程遥今天脾气不好&quot;。</p><p>我说，我不写这个。</p><p>她说，那你写什么。</p><p>我说，我写&quot;2月14，立牌一件，她全出，因为她今天晚上不想让我替她想&quot;。</p><p>她说，你连日期都记。</p><p>我说，我什么都记。</p><p>她说，你把这句写完。</p><p>她说，你写完你在后面加一句。</p><p>我说，加什么。</p><p>她说，加&quot;这个我们以后还会遇到&quot;。</p><p>我说，你为什么让我加这句。</p><p>她说，因为我知道。</p><p>她说，我们两个以后每遇到一次这种二十四块钱，你都要替我想一次。</p><p>她说，我每一次都不收。</p><p>她说，你要把这句话写在第一件上面，你以后翻到你就能想起来你今天晚上讲过。</p><p>那天夜里我写完了。</p><p>我写：2月14，立牌一件，她全出，因为她今天晚上不想让我替她想。</p><p>我写：这个我们以后还会遇到。</p>',139)])])}const l=t(_,[["render",u]]);export{d as __pageData,l as default};
